SELECT 'batch_025_e3640d3b_wav_08' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-9259e6f5144348d3b9f1881d95c31d97','sm-upload-00474c5a-882','sm-upload-12d68563-b7d','sm-upload-2e7224ec-39c','sm-upload-3020e076-7c7','sm-upload-47be279d-a1f','sm-upload-4af9cee4-3d9','sm-upload-5080d6c6-ec3') AND album_id='al-3601f0337902ef9583048198e3640d3b') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-9259e6f5144348d3b9f1881d95c31d97','sm-upload-00474c5a-882','sm-upload-12d68563-b7d','sm-upload-2e7224ec-39c','sm-upload-3020e076-7c7','sm-upload-47be279d-a1f','sm-upload-4af9cee4-3d9','sm-upload-5080d6c6-ec3') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-3601f0337902ef9583048198e3640d3b' AND name='sakuya薯片~THE NOCTURNE') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-3601f0337902ef9583048198e3640d3b') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-3601f0337902ef9583048198e3640d3b') AS calculated_size;
